import { createMiddleware } from "hono/factory";
import { getDb } from "../db";
import { createAuth } from "../lib/better-auth";
import type { R2BucketRef } from "../lib/asset-util";

export type HonoEnv = {
	Bindings: Env;
	Variables: {
		db: ReturnType<typeof getDb>;
		// Uses createAuth (not betterAuth directly) for proper TypeScript inference
		// of plugin methods like betterAuth.api.verifyApiKey, createApiKey, etc.
		betterAuth: ReturnType<typeof createAuth>;
		authentication?: AuthType;
		userAssets: R2BucketRef;
	};
};

export const contextMiddleware = createMiddleware<HonoEnv>(async (c, next) => {
	// Initialize database
	const {
		DB,
		USER_ASSETS_BUCKET: userAssetsBucket,
		VITE_GITHUB_CLIENT_ID: githubClientId,
		GITHUB_CLIENT_SECRET: githubClientSecret,
		VITE_GOOGLE_CLIENT_ID: googleClientId,
		GOOGLE_CLIENT_SECRET: googleClientSecret,
		BETTER_AUTH_SECRET: betterAuthSecret,
		RESEND_API_KEY: resendApiKey,
		ADMIN_USER_IDS: adminUserIdsEnv,
	} = c.env;

	const adminUserIds = adminUserIdsEnv
		? adminUserIdsEnv
				.split(",")
				.map((id) => id.trim())
				.filter(Boolean)
		: undefined;

	const db = getDb(DB);

	// Get origin from request for passkey configuration
	const origin =
		c.req.header("origin") ||
		`${c.req.header("x-forwarded-proto") || "https"}://${c.req.header("host") || "localhost"}`;

	const auth = createAuth({
		db,
		betterAuthSecret,
		githubClientId,
		githubClientSecret,
		googleClientId,
		googleClientSecret,
		origin,
		resendApiKey,
		adminUserIds,
	});
	c.set("db", db);
	c.set("betterAuth", auth);
	c.set("userAssets", {
		bucketName: "scorebrawl-user-assets",
		bucket: userAssetsBucket,
	});

	await next();
});

// for better auth cli
export const auth = createAuth({
	db: undefined as unknown as ReturnType<typeof getDb>,
	betterAuthSecret: "",
});

export type AuthType = {
	user: typeof auth.$Infer.Session.user;
	session: typeof auth.$Infer.Session.session;
};

import { env } from "cloudflare:test";
import { randCompanyName, randEmail, randFullName, randSlug } from "@ngneat/falso";
import { eq } from "drizzle-orm";
import { getDb } from "../../src/db/index";
import { user } from "../../src/db/schema/auth-schema";
import { createAuth } from "../../src/lib/better-auth";

export interface UserInput {
	email?: string;
	password?: string;
	name?: string;
}

export interface LeagueInput {
	name?: string;
	slug?: string;
}

export interface AuthContext {
	sessionToken: string;
	user: UserInput & { id: string; email: string; password: string; name: string };
	league: LeagueInput & { id: string; name: string; slug: string };
}

/**
 * Generate user input with defaults
 */
export function aUser(overrides: UserInput = {}): UserInput & {
	email: string;
	password: string;
	name: string;
} {
	return {
		email: randEmail(),
		password: "password123",
		name: randFullName(),
		...overrides,
	};
}

/**
 * Generate league input with defaults
 */
export function aLeague(overrides: LeagueInput = {}): LeagueInput & {
	name: string;
	slug: string;
} {
	const name = overrides.name ?? randCompanyName();
	return {
		name,
		slug: randSlug(),
		...overrides,
	};
}

/**
 * Helper to create auth headers with session token
 */
export function authHeaders(sessionToken: string): Record<string, string> {
	return {
		Cookie: `better-auth.session_token=${sessionToken}`,
	};
}

/**
 * Create an authenticated context with a user and league
 */
export async function createAuthContext(
	options: { user?: UserInput; league?: LeagueInput } = {}
): Promise<AuthContext> {
	const db = getDb(env.DB);
	const auth = createAuth({
		db,
		betterAuthSecret: env.BETTER_AUTH_SECRET,
	});

	const userInput = aUser(options.user);
	const orgInput = aLeague(options.league);

	// Sign up a test user
	const { headers } = await auth.api.signUpEmail({
		body: userInput,
		returnHeaders: true,
	});

	const cookies = headers.get("set-cookie");
	const token = cookies?.match(/better-auth\.session_token=([^;]+)/)?.[1];
	if (!token) throw new Error("No session token in response");
	let sessionToken = token;

	// Create an organization
	const org = await auth.api.createOrganization({
		body: orgInput,
		headers: new Headers(authHeaders(sessionToken)),
	});
	if (!org) throw new Error("Failed to create organization");

	// Set the organization as active
	const { headers: activeHeaders } = await auth.api.setActiveOrganization({
		body: { organizationId: org.id },
		headers: new Headers(authHeaders(sessionToken)),
		returnHeaders: true,
	});

	// Update session token if new one was issued
	const newCookies = activeHeaders.get("set-cookie");
	if (newCookies) {
		const newToken = newCookies.match(/better-auth\.session_token=([^;]+)/)?.[1];
		if (newToken) sessionToken = newToken;
	}

	// Fetch the created user to get their ID
	const [createdUser] = await db.select().from(user).where(eq(user.email, userInput.email));
	if (!createdUser) throw new Error("Failed to fetch created user");

	return {
		sessionToken,
		user: {
			...userInput,
			id: createdUser.id,
		},
		league: {
			id: org.id,
			name: org.name,
			slug: org.slug,
		},
	};
}

/**
 * Create an additional league for an authenticated user
 */
export async function createLeague(
	sessionToken: string,
	overrides: LeagueInput = {}
): Promise<{ id: string; name: string; slug: string }> {
	const db = getDb(env.DB);
	const auth = createAuth({
		db,
		betterAuthSecret: env.BETTER_AUTH_SECRET,
	});

	const orgInput = aLeague(overrides);

	const org = await auth.api.createOrganization({
		body: orgInput,
		headers: new Headers(authHeaders(sessionToken)),
	});

	if (!org) throw new Error("Failed to create organization");

	return {
		id: org.id,
		name: org.name,
		slug: org.slug,
	};
}

/**
 * Create an authenticated user without a league
 */
export async function createUser(overrides: UserInput = {}): Promise<{
	sessionToken: string;
	user: UserInput & { id: string; email: string; password: string; name: string };
}> {
	const db = getDb(env.DB);
	const auth = createAuth({
		db,
		betterAuthSecret: env.BETTER_AUTH_SECRET,
	});

	const userInput = aUser(overrides);

	const { headers } = await auth.api.signUpEmail({
		body: userInput,
		returnHeaders: true,
	});

	const cookies = headers.get("set-cookie");
	const token = cookies?.match(/better-auth\.session_token=([^;]+)/)?.[1];
	if (!token) throw new Error("No session token in response");

	// Fetch the created user to get their ID
	const [createdUser] = await db.select().from(user).where(eq(user.email, userInput.email));
	if (!createdUser) throw new Error("Failed to fetch created user");

	return {
		sessionToken: token,
		user: {
			...userInput,
			id: createdUser.id,
		},
	};
}

export function bearerHeaders(token: string): Record<string, string> {
	return { Authorization: `Bearer ${token}` };
}
